1	syntax = "proto3";
2	
3	package memos.store;
4	
5	option go_package = "gen/store";
6	
7	message MemoPayload {
8	  Property property = 1;
9	
10	  Location location = 2;
11	
12	  repeated string tags = 3;
13	
14	  // The calculated properties from the memo content.
15	  message Property {
16	    bool has_link = 1;
17	    bool has_task_list = 2;
18	    bool has_code = 3;
19	    bool has_incomplete_tasks = 4;
20	    // The title extracted from the first H1 heading, if present.
21	    string title = 5;
22	  }
23	
24	  message Location {
25	    string placeholder = 1;
26	    double latitude = 2;
27	    double longitude = 3;
28	  }
29	}
